#[test]
fn is_unit_type_matches_the_original() {
    let mut n = 0;
    for &(b33, f5c, mov, cls, eth, mim, atk, flags, k0, k1, t0, t1, mask) in IS_UNIT_TYPE {
        let v = UnitView {
            type_id: b33 << 24,
            illusion: f5c & 0x4000_0000 != 0,
            dead: f5c >> 8 & 1 != 0,
            structure: f5c & 0x1_0000 != 0,
            movement: mov,
            class_flags: cls,
            ethereal: eth,
            magic_immune: mim,
        };
        let w = atk.then_some(WeaponView {
            kind: [k0, k1],
            targs: [t0, t1],
            enabled: [flags >> 19 & 1 != 0, flags >> 20 & 1 != 0],
        });
        for t in 0..ty::COUNT {
            let got = match simple_test(&v, t) {
                Some(b) => b,
                None if (5..=8).contains(&t) => attack_test(t, w.as_ref()),
                None => false, // the state values: the vectors use an empty ability list
            };
            assert_eq!(got, mask >> t & 1 != 0, "value {t}, vector {n}");
        }
        n += 1;
    }
    assert!(n > 100);
}

#[test]
fn is_unit_id_type_matches_the_original() {
    for &(id, structure, movement, class, weapons_on, k0, k1, t0, t1, mask) in ID_TYPE {
        let v = IdView {
            structure: structure != 0,
            movement,
            classification: class,
            weapons_on,
            kind: [k0, k1],
            targs: [t0, t1],
        };
        for t in 0..ty::COUNT {
            assert_eq!(id_type_test(id, &v, t), mask >> t & 1 != 0, "id {id:#x} value {t}");
        }
    }
}
